using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

var mlContext = new MLContext(seed: 0);
var dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "tickets.csv");
Console.WriteLine($"Loading from: {dataPath}");

IDataView dataView = mlContext.Data.LoadFromTextFile<TicketData>(
    dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

Console.WriteLine($"Rows: {dataView.GetColumn<string>("Subject").Count()}");

var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
    .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
    .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
    .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

Console.WriteLine("Training...");
var model = pipeline.Fit(dataView);
Console.WriteLine("Training done.");

var predEngine = mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(model);
var result = predEngine.Predict(new TicketData { Subject = "Payment failed", Description = "My credit card was declined", Priority = 1 });
Console.WriteLine($"Predicted: {result.PredictedCategory}");
Console.WriteLine($"Scores: {string.Join(", ", result.Score)}");

// Try cross-validation
Console.WriteLine("Cross-validating...");
try {
    var cvResults = mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 2);
    Console.WriteLine($"CV folds: {cvResults.Count()}");
    foreach (var r in cvResults)
        Console.WriteLine($"  Accuracy: {r.Metrics.MacroAccuracy}");
} catch (Exception ex) {
    Console.WriteLine($"CV failed: {ex.Message}");
}
EOF
